mapper.select:
SELECT C.*, CG.CustGroupName AS CustGroupName, Comp.CompName, Comp.CompLogoImg,
       B.BranchName, D.DeptName, Dt.DutyName, Ch.ChnlName
FROM shopion.tPrfCust C
LEFT OUTER JOIN shopion.tPrfComp Comp ON C.CompCode = Comp.CompCode
LEFT OUTER JOIN shopion.tPrfBranch B ON C.CompCode = B.CompCode AND C.BranchId = B.BranchId
LEFT OUTER JOIN shopion.tPrfDept D ON C.BranchId = D.BranchId AND C.DeptCode = D.DeptCode
LEFT OUTER JOIN shopion.tPrfDuty Dt ON C.CompCode = Dt.CompCode AND C.DutyId = Dt.DutyId
LEFT OUTER JOIN shopion.tPrfCustGroup CG ON C.CustGroupCode = CG.CustGroupCode
LEFT OUTER JOIN shopion.tStrChnl Ch ON C.ChnlCode = Ch.ChnlCode

    AND Ch.SvcCode = #{pSvcCode}
    AND C.ChnlCode = #{pChnlCode}
    AND C.CustGroupCode = #{pCustGroupCode}
    AND C.CustName LIKE CONCAT('%',#{pCustName},'%')
    AND C.LoginId LIKE CONCAT('%',#{pLoginId},'%')
    AND C.CustId = #{pCustId}

ORDER BY C.${sidx} ${sord}
LIMIT #{topCnt}, #{countPerPage}

SELECT * FROM (
SELECT C.CustId, C.CustName, C.Email, C.HomePhoneNo, C.MobilePhoneNo, C.MobileSvc, C.FaxNo,
       C.Zipcode, C.Addr1, C.Addr2, C.LoginId, C.Passwd, Comp.CompName, Comp.CompLogoImg,
       B.BranchName, D.DeptName, Dt.DutyName,
       C.CompCode, C.BranchId, C.DeptCode, C.DutyId, C.MailReciptYn, C.SmsReciptYn,
       C.Remark, C.State, C.RegistDate, C.RegistName, C.RegistId, C.ChangeDate, C.ChangeName, C.ChangeId
FROM shopion.tPrfCust C
INNER JOIN shopion.tPrfComp Comp ON C.CompCode = Comp.CompCode
INNER JOIN shopion.tPrfBranch B ON C.CompCode = B.CompCode AND C.BranchId = B.BranchId
INNER JOIN shopion.tPrfDept D ON C.BranchId = D.BranchId AND C.DeptCode = D.DeptCode
INNER JOIN shopion.tPrfDuty Dt ON C.CompCode = Dt.CompCode AND C.DutyId = Dt.DutyId

    AND C.ChnlCode = #{pChnlCode}
    AND C.CompCode = #{pCompCode}

        AND C.BranchId = #{pBranchId}
        AND C.DeptCode = #{pDeptCode}

    AND C.CustName LIKE CONCAT('%',#{pCustName},'%')

) T1
ORDER BY ${sidx} ${sord}

mapper.update:
UPDATE shopion.tPrfCust SET
    Passwd = #{passwd}, ChangeDate = NOW(), ChangeName = #{changeName}
WHERE CustId = #{custId}

UPDATE shopion.tPrfCust SET
    LastLoginTime = NOW(), ChangeDate = NOW(), ChangeId = #{loginId}, ChangeName = #{custName}
WHERE CustId = #{custId}
